/**
 * Sprint 8 — bundled per-rewayat ayah-timing data.
 *
 * Why this exists:
 *   Qariah's reciters are not in MP3Quran or QuranCDN's catalogs (the
 *   two upstream timing sources `TimestampFetchService` knows about), so
 *   the Mushaf Player Settings reciter dropdown was permanently empty
 *   regardless of how good our audio is. This module is a third source —
 *   `'local'` — that ships timing JSON inside the app bundle.
 *
 * Adding a reciter:
 *   1. Get per-ayah timing data from your source-of-truth (waveform tool,
 *      manual ear-marking, etc.) into the `AyahTimestamp[]` shape:
 *        { surahNumber, ayahNumber, timestampFrom, timestampTo, durationMs }
 *      with all millisecond values.
 *   2. Drop the data here as `BUNDLED_TIMINGS[<rewayat-id>][<surah-number>]`.
 *   3. Nothing else — `config/branding.js` routes this registry through the
 *      upstream RFC-019 seam (`branding.timestampLocalProvider` +
 *      `branding.timestampLocalSurahList`, Bayaan #305), so
 *      `TimestampFetchService.hasSource()` picks the rewayat up and it
 *      appears in the Mushaf Player Settings dropdown automatically.
 *
 * Structure:
 *   `BUNDLED_TIMINGS` is keyed by `Rewayat.id` (UUID from catalog.json),
 *   then by surah number (1–114). The inner array MUST be sorted by
 *   `ayahNumber` ascending — `mushafPlayerStore` and follow-along
 *   tracking assume order.
 *
 * Bundle size:
 *   A typical surah of ~10 ayat at 24 bytes each ≈ 250 bytes; 114 surahs
 *   per rewayat ≈ 30 KB. Even 5 reciters fully bundled = 150 KB. Pure
 *   JSON, gzip-friendly. Safe to bundle in the JS bundle.
 *
 * Future:
 *   - When the dataset gets large enough that bundle size matters,
 *     migrate to per-surah JSON files loaded lazily via `require()`.
 *   - When a remote-fetch path is appropriate (e.g. R2-hosted timing
 *     data we author ourselves), add a `'remote'` source to
 *     `TimestampSource` and a corresponding fetch path.
 */

