/** True if any surah has bundled timings for this rewayat. */
export function hasBundledTimings(
  rewayatId: string,
  surahNumber?: number,
): boolean {
  const byRewayat = BUNDLED_TIMINGS[rewayatId];
  if (!byRewayat) return false;
  if (surahNumber === undefined) {
    return Object.keys(byRewayat).length > 0;
  }
  const arr = byRewayat[surahNumber];
  return Array.isArray(arr) && arr.length > 0;
}

/** Returns sorted timestamps or null if not bundled. */
export function getBundledTimings(
  rewayatId: string,
  surahNumber: number,
): AyahTimestamp[] | null {
  const byRewayat = BUNDLED_TIMINGS[rewayatId];
  if (!byRewayat) return null;
  const arr = byRewayat[surahNumber];
  if (!Array.isArray(arr) || arr.length === 0) return null;
  return arr;
}

/**
 * RFC-019 coverage signal — the exact list of surah numbers this bundle
 * covers for a rewayat, or `null` when the rewayat has no bundled timings.
 *
 * Feeds `branding.timestampLocalSurahList` (config/branding.js), which
 * `TimestampFetchService.hasSource` / `hasSurah` treat as an EXACT
 * allow-list (empty/null → no local coverage — NOT "all surahs"). The
 * RFC-019 contract requires the coverage list and the data provider to
 * agree, so entries whose timing array is empty are filtered out.
 * Sorted ascending for determinism.
 */
export function getBundledSurahList(rewayatId: string): number[] | null {
  const byRewayat = BUNDLED_TIMINGS[rewayatId];
  if (!byRewayat) return null;
  return Object.keys(byRewayat)
    .map(Number)
    .filter(n => hasBundledTimings(rewayatId, n))
    .sort((a, b) => a - b);
}
